import{_ as n}from"./chunks/ugso_callmebot_signal_action.khNgQHDV.js";import{_ as t,o as r,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const l="/assets/callmebot-signal/de.png",f=JSON.parse('{"title":"CallMeBot Signal","description":"Signal-Textnachrichten aus Home Assistant mit Empfängerprofilen und Blockly.","frontmatter":{"title":"CallMeBot Signal","description":"Signal-Textnachrichten aus Home Assistant mit Empfängerprofilen und Blockly."},"headers":[],"relativePath":"projects/callmebot-signal/index.md","filePath":"projects/callmebot-signal/index.md","lastUpdated":1792862850000}'),s={name:"projects/callmebot-signal/index.md"};function o(d,e,c,h,g,u){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="callmebot-signal" tabindex="-1">CallMeBot Signal <a class="header-anchor" href="#callmebot-signal" aria-label="Permalink to &quot;CallMeBot Signal&quot;">​</a></h1><p>Beta <strong>HA-App 0.1.2</strong> im <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot_signal" target="_blank" rel="noreferrer">gemeinsamen Repository mit Blocks for HA</a>. Vollständig <strong>DE/EN/FR</strong>, Systemsprache und Hell/Dunkel/System. Eigenständige UGSo-Implementierung, inspiriert von <a href="https://github.com/derAlff/ioBroker.signal-cmb" target="_blank" rel="noreferrer">ioBroker.signal-cmb</a>.</p><p><img src="'+l+'" alt="Signal-Oberfläche auf Deutsch"></p><h2 id="einrichtung" tabindex="-1">Einrichtung <a class="header-anchor" href="#einrichtung" aria-label="Permalink to &quot;Einrichtung&quot;">​</a></h2><ol><li>Repository <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> im HA-App-Store hinzufügen und <strong>CallMeBot Signal</strong> installieren.</li><li>MQTT in HA einrichten, App starten und Oberfläche über Ingress öffnen. Der interne MQTT-Dienst liefert bevorzugt die Zugangsdaten; App-Optionen dienen als Fallback.</li><li>Den aktuellen Bot-Kontakt aus der <a href="https://www.callmebot.com/blog/free-api-signal-send-messages/" target="_blank" rel="noreferrer">offiziellen Signal-Aktivierungsanleitung</a> verwenden. In <strong>Signal</strong> die dort angegebene Freischaltnachricht senden und den <strong>Signal-API-Schlüssel</strong> abwarten.</li><li>Profil-ID, Anzeigename, eigene internationale Telefonnummer <strong>mit +</strong> oder <strong>Signal-UUID</strong> sowie den passenden Schlüssel speichern. Bei verborgener Telefonnummer kann der Bot eine UUID liefern. Den Wert aus dem Aktivierungslink unverändert übernehmen.</li><li>Standardprofil wählen. „Nachricht senden“ sendet wirklich an das ausgewählte gespeicherte Profil.</li></ol><p>WhatsApp-Schlüssel gelten nicht für Signal. Beide Apps können gleichzeitig laufen: getrennte Profile, MQTT-Themen, Client-IDs und Diagnose-Entitäten. Die <a href="./../callmebot/">WhatsApp-App</a> behält ihre bisherigen technischen IDs.</p><h2 id="blockly-und-profilauswahl" tabindex="-1">Blockly und Profilauswahl <a class="header-anchor" href="#blockly-und-profilauswahl" aria-label="Permalink to &quot;Blockly und Profilauswahl&quot;">​</a></h2><p>Seit <strong>Blocks for HA 0.1.50</strong>: <strong>Nachrichten → Signal · CallMeBot</strong>.</p><p><img src="'+n+'" alt="Signal-Block"></p><p>Profilfeld anklicken, nach Name/ID suchen und auswählen. Leer bedeutet Standardempfänger. Sichtbar ist der Name; gespeichert wird die Profil-ID. Text, Variable oder Jinja als Nachricht anschließen. Protokoll: nur Fehler, keins oder Info. Der Block erzeugt natives <code>mqtt.publish</code>; JSON wird nach der Template-Auswertung serialisiert.</p><p>Die App veröffentlicht einen Katalog auf <code>ugso/callmebot_signal/profiles</code> und per MQTT-Discovery die Diagnose-Entität <strong><code>sensor.ugso_callmebot_signal_profiles</code></strong>. Zustand: Profilanzahl. Attribute: IDs, Namen, Standardprofil und Quellenmarker, <strong>keine Telefonnummer, Nachricht oder Schlüssel</strong>. Blocks erkennt den Quellenmarker auch nach Umbenennung der Entität. Standard-Discovery-Präfix: <code>homeassistant</code>.</p><p>Bei fehlender Verbindung Profil-ID manuell eingeben oder leer lassen. Ungültige/gelöschte IDs werden nicht automatisch ersetzt. JSON-Projekte erhalten den Komfortblock; YAML-Import stellt den Versand als allgemeine HA-/MQTT-Aktion dar.</p><h2 id="protokoll-und-grenzen" tabindex="-1">Protokoll und Grenzen <a class="header-anchor" href="#protokoll-und-grenzen" aria-label="Permalink to &quot;Protokoll und Grenzen&quot;">​</a></h2><ul><li>Versand: <code>ugso/callmebot_signal/send</code>, QoS 0, <strong>retain false</strong>.</li><li>Beispiel: <code>{&quot;profile&quot;:&quot;default&quot;,&quot;message&quot;:&quot;Hallo aus HA&quot;,&quot;loglevel&quot;:&quot;errors&quot;}</code>. Leeres Profil verwendet den Standardempfänger.</li><li>Ergebnis: <code>ugso/callmebot_signal/result</code>, nicht retained, nur Profil, Anfrage-ID, Status und Zeit.</li><li>Katalog und Verfügbarkeit: <code>ugso/callmebot_signal/profiles</code> und <code>ugso/callmebot_signal/availability</code>, retained. Verfügbarkeit zeigt die Broker-Verbindung.</li><li>Maximal 16 Profile, 4000 Zeichen, Warteschlange 20, mindestens 10 Sekunden zwischen Versandversuchen je Profil. Schnellere Befehle werden abgelehnt.</li><li>Optionale <code>request_id</code>: eine Stunde Dublettenprüfung, maximal 1000 IDs. Keine automatischen Wiederholungen oder Wiedergabe nach Neustart; retained Befehle werden abgelehnt.</li><li>Eine Signal-App-Instanz pro Broker. Schreibrechte auf Versandthemen beschränken. Externe MQTT-TLS-Konfiguration ist nicht enthalten.</li></ul><p>Diese App sendet <strong>Textnachrichten an eigene aktivierte Empfänger</strong>. Bilder, Gruppen und Antworten sind nicht implementiert. <code>accepted</code> bestätigt nur die API-Annahme. Empfänger, Schlüssel und Nachricht gehen per HTTPS an <code>https://signal.callmebot.com/signal/send.php</code>.</p><p>Schlüssel bleiben in der privaten Backend-Datei <code>/data/profiles.json</code>, werden nicht an Browser/MQTT/Blockly ausgegeben und nicht protokolliert. Die Datei ist nicht verschlüsselt und in HA-Backups enthalten; Backups entsprechend schützen.</p><h2 id="prufstand" tabindex="-1">Prüfstand <a class="header-anchor" href="#prufstand" aria-label="Permalink to &quot;Prüfstand&quot;">​</a></h2><p>Backend, UUID-/Nummernvalidierung, MQTT-Protokoll, Blockly/Jinja-Export, DE/EN/FR und mobile Ansicht sind mit Testdaten geprüft. Echte Signal-Zustellung und Installation unter HA-Supervisor sind mit der eigenen Einrichtung zu prüfen. Automatisierte Tests senden keine echten Nachrichten.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot_signal" target="_blank" rel="noreferrer">Quellcode</a> · Apache-2.0 · Unabhängiges Community-Projekt.</p><h2 id="beta-historie-profilsicherung-und-mqtt-tls" tabindex="-1">Beta: Historie, Profilsicherung und MQTT-TLS <a class="header-anchor" href="#beta-historie-profilsicherung-und-mqtt-tls" aria-label="Permalink to &quot;Beta: Historie, Profilsicherung und MQTT-TLS&quot;">​</a></h2><p>Die Historie enthält bis zu 200 dauerhaft gespeicherte Einträge mit Zeitpunkt, Profil-ID, Quelle und Ergebnis. Filter nach Profil oder Fehlerstatus und bestätigtes Löschen sind verfügbar. Nachrichten, Telefonnummern, API-Schlüssel und Anfrage-IDs werden nicht in der Historie gespeichert. „Angenommen“ bestätigt weiterhin nur die Annahme durch CallMeBot, keine Zustellung. Bei Speicherfehlern wird der Versand nicht wiederholt.</p><p>Die Profilsicherung verschlüsselt Profile einschließlich Telefonnummern, API-Schlüsseln und Standardempfänger mit AES-GCM und einem aus dem Sicherungspasswort abgeleiteten Schlüssel (scrypt). Mindestens 12 Zeichen; Passwort separat aufbewahren. Es wird nicht gespeichert. Ohne Passwort ist keine Wiederherstellung möglich. Wiederherstellen ersetzt die Profile erst nach Bestätigung und erfolgreicher Prüfung; falsches Passwort, beschädigte Dateien oder Sicherungen der anderen CallMeBot-App ändern nichts. Bei wartenden Versandversuchen wird die Wiederherstellung abgewiesen. MQTT-Zugangsdaten und Historie sind nicht enthalten; für diese weiterhin die vollständige HA-App-Sicherung verwenden.</p><p>Unter MQTT-Verbindung bleibt „HA-Broker automatisch verwenden“ der bisherige Standard. Für einen externen Broker die Automatik deaktivieren und Host, Port, Benutzer und Passwort angeben. TLS prüft Zertifikat und Hostname; eigene CA und Client-Zertifikat/Schlüssel sind als PEM-Datei oder Text möglich. TLS-Port passend wählen, häufig 8883. Leere Geheimnisfelder behalten gespeicherte Werte. HA/Blocks müssen diesen Broker verwenden oder die Send-/Result-/Profil-/Discovery-Topics zwischen den Brokern weiterleiten; eine externe Verbindung allein ersetzt keine Broker-Bridge.</p><p>Bestehende profiles.json, Profile, Schlüssel, MQTT-Themen und Entitäts-IDs bleiben erhalten. Neue Historie: /data/history.json; ausdrücklich gespeicherte MQTT-Einstellungen: /data/mqtt.json. Die Konfiguration wird beim Update nicht automatisch umgeschrieben. Alle neuen Oberflächentexte sind DE/EN/FR.</p><p>Die Oberfläche und Beschreibung heißen Beta. Home Assistant unterstützt keinen nativen stage-Wert beta; der gültige technische Status experimental bleibt deshalb bestehen. <a href="https://developers.home-assistant.io/docs/apps/configuration/" target="_blank" rel="noreferrer">HA-Konfiguration</a>.</p>',25)])])}const b=t(s,[["render",o]]);export{f as __pageData,b as default};
